using System;using System.IO;using System.Collections.Generic;using System.Threading;using System.Globalization;
namespace OsuLegacy {
 public interface IMirrorTransport {void Fetch(string path,string target,int maximum,Func<bool> cancelled,Action<int,int> progress);}
 public sealed class OnlineBeatmaps {
  private readonly Dictionary<string,double> ratings=new Dictionary<string,double>();private readonly object ratingsLock=new object();
  private static string RatingKey(int set,int mode,string name){return set+"|"+mode+"|"+Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(name??""));}
  public double Rating(int set,int mode,string name){lock(ratingsLock){double stars;return ratings.TryGetValue(RatingKey(set,mode,name),out stars)?stars:-1;}}
  private void RememberRatings(List<MirrorSet> sets){lock(ratingsLock){foreach(var set in sets)foreach(var d in set.Difficulties)ratings[RatingKey(set.Id,d.Mode,d.Name)]=d.Stars;try{string path=Path.Combine(cache,"ratings.tsv"),stage=path+".part";using(var writer=new StreamWriter(stage)){foreach(var pair in ratings)writer.WriteLine(pair.Key+"\t"+pair.Value.ToString("R",CultureInfo.InvariantCulture));}if(File.Exists(path))File.Delete(path);File.Move(stage,path);}catch(IOException){}catch(UnauthorizedAccessException){}}}
  private void LoadRatings(){try{string path=Path.Combine(cache,"ratings.tsv");if(!File.Exists(path)||new FileInfo(path).Length>2097152)return;foreach(string line in File.ReadAllLines(path)){int tab=line.IndexOf('\t');double n;if(tab>0 && double.TryParse(line.Substring(tab+1),NumberStyles.Float,CultureInfo.InvariantCulture,out n) && !double.IsNaN(n)&&n>=0&&n<=100)ratings[line.Substring(0,tab)]=n;}}catch(IOException){}catch(UnauthorizedAccessException){}}

  private sealed class SearchWork {public int Offset;public string Path,Temp,Error="";public bool Cached;public List<MirrorSet> Sets;public volatile bool Finished,Cancelled;}
  private sealed class DownloadWork {public MirrorSet Set;public string Temp,Final,Path,Error="";public volatile bool Finished,Cancelled;public int Bytes,Total;}
  private readonly IMirrorTransport transport;private readonly string cache,imports;private readonly object workerLock=new object();private SearchWork current,handled,pending,active;private bool running;private int sequence,assetVersion,paintedAssets,paintedBytes;private long paintedAt;private readonly Dictionary<int,bool> queuedImports=new Dictionary<int,bool>();public bool ImportQueued(int id){return queuedImports.ContainsKey(id);}
  private DownloadWork download;private bool downloadHandled;
  public readonly MirrorQuery Query=new MirrorQuery();public List<MirrorSet> Results=new List<MirrorSet>();public string Error="",DownloadError="";public bool Cached,HasMore=true;public int Offset,Revision;public Action WorkerStarted;public Action<MirrorSet,string> Downloaded;public Action<string> DownloadFailed;
  public bool Searching{get{return current!=null && !current.Finished;}}public bool Downloading{get{return download!=null && !download.Finished;}}public int DownloadId{get{return download==null?0:download.Set.Id;}}public double DownloadProgress{get{return download==null || download.Total<=0?-1:Math.Min(1,(double)download.Bytes/download.Total);}}public int DownloadBytes{get{return download==null?0:download.Bytes;}}
  public OnlineBeatmaps(string root,IMirrorTransport transport){this.transport=transport;cache=Path.Combine(root,"BrowserCache");imports=Path.Combine(root,"Imports");Directory.CreateDirectory(cache);Directory.CreateDirectory(imports);LoadRatings();}
  public void Search(bool more){if(more && (Searching || !HasMore))return;int offset=more?Offset+MirrorQuery.PageSize:0;if(!more){Results=new List<MirrorSet>();Offset=0;HasMore=true;}Error="";var work=new SearchWork{Offset=offset,Path=Query.Path(offset),Temp=Path.Combine(cache,"search-"+(++sequence)+".part")};current=work;Revision++;lock(workerLock){if(pending!=null)pending.Cancelled=true;if(active!=null)active.Cancelled=true;pending=work;if(!running){running=true;new Thread(SearchLoop){IsBackground=true}.Start();}}}
  public void CancelSearch(){lock(workerLock){if(active!=null)active.Cancelled=true;if(pending!=null){pending.Cancelled=true;pending=null;}if(current!=null){current.Cancelled=true;current.Finished=true;}Error="Search cancelled";Revision++;}}
  private static string Key(string path){uint hash=2166136261;foreach(char c in path){hash^=c;hash*=16777619;}return hash.ToString("x8",CultureInfo.InvariantCulture);}
  private string CachedJson(SearchWork work,bool fresh){string file=Path.Combine(cache,"query-"+Key(work.Path)+".json");if(!File.Exists(file) || new FileInfo(file).Length>2*1024*1024+8192 || (fresh && (DateTime.UtcNow-File.GetLastWriteTimeUtc(file)).TotalSeconds>30))return null;string value=File.ReadAllText(file);int split=value.IndexOf('\n');return split>=0 && value.Substring(0,split)==work.Path?value.Substring(split+1):null;}
  private void SearchLoop(){if(WorkerStarted!=null)WorkerStarted();while(true){SearchWork work;lock(workerLock){work=pending;pending=null;if(work==null){active=null;running=false;return;}active=work;}try{string json=CachedJson(work,true);if(json==null){try{transport.Fetch(work.Path,work.Temp,2*1024*1024,delegate{return work.Cancelled;},null);if(work.Cancelled)continue;json=File.ReadAllText(work.Temp);}catch(Exception){if(work.Cancelled)continue;json=CachedJson(work,false);if(json==null)throw;work.Cached=true;}}else work.Cached=true;work.Sets=MirrorSet.Parse(json);RememberRatings(work.Sets);if(!work.Cached && work.Sets.Count>0){string target=Path.Combine(cache,"query-"+Key(work.Path)+".json");File.WriteAllText(work.Temp,work.Path+"\n"+json);if(File.Exists(target))File.Delete(target);File.Move(work.Temp,target);}}
   catch(Exception error){work.Error=error.Message;}finally{if(File.Exists(work.Temp))File.Delete(work.Temp);work.Finished=true;}
   if(work.Cancelled || work.Sets==null)continue;foreach(MirrorSet set in work.Sets){if(work.Cancelled)break;string target=Path.Combine(cache,"cover-"+set.Id+".jpg"),stage=target+".part";try{if(!File.Exists(target) || new FileInfo(target).Length==0){transport.Fetch("/v3/osu/beatmaps/cover/"+set.Id+"?type=card",stage,2*1024*1024,delegate{return work.Cancelled;},null);if(work.Cancelled)break;using(var image=File.OpenRead(stage)){int a=image.ReadByte(),b=image.ReadByte();if(!((a==255 && b==216)||(a==137 && b==80)))throw new FormatException("Invalid cover image");}File.Move(stage,target);}set.CoverPath=target;Interlocked.Increment(ref assetVersion);}catch{ }finally{if(File.Exists(stage))File.Delete(stage);}}
  }}
  public void Download(MirrorSet set,bool noVideo){if(Downloading || set==null)return;DownloadError="";downloadHandled=false;paintedBytes=0;var work=new DownloadWork{Set=set,Path="/api/v1/hinai/d/"+set.Id+(noVideo?"n":""),Temp=Path.Combine(imports,"hinai-"+set.Id+(noVideo?"-novideo":"")+".osz.part"),Final=Path.Combine(imports,"hinai-"+set.Id+(noVideo?"-novideo":"")+".osz")};download=work;Revision++;new Thread(delegate(){if(WorkerStarted!=null)WorkerStarted();try{transport.Fetch(work.Path,work.Temp,256*1024*1024,delegate{return work.Cancelled;},delegate(int bytes,int total){work.Bytes=bytes;work.Total=total;});if(work.Cancelled)return;using(var stream=File.OpenRead(work.Temp)){if(stream.Length<22 || stream.ReadByte()!=80 || stream.ReadByte()!=75 || stream.ReadByte()!=3 || stream.ReadByte()!=4)throw new FormatException("Mirror did not return a beatmap archive");}if(File.Exists(work.Final))throw new IOException("This archive is already downloaded; import it from Solo.");File.Move(work.Temp,work.Final);}catch(Exception error){work.Error=error.Message;}finally{if(File.Exists(work.Temp))File.Delete(work.Temp);work.Finished=true;}}){IsBackground=true}.Start();}
  public void CancelDownload(){if(download!=null)download.Cancelled=true;Revision++;}
  public bool Poll(){bool changed=false;if(current!=null && current!=handled && current.Finished){handled=current;if(!current.Cancelled){if(current.Error!="")Error=current.Error;else{if(current.Offset==0)Results=new List<MirrorSet>();foreach(var set in current.Sets){if(!Results.Exists(delegate(MirrorSet old){return old.Id==set.Id;}))Results.Add(set);}Offset=current.Offset;HasMore=current.Sets.Count>0;Cached=current.Cached;Error="";}changed=true;}}
   int assets=Interlocked.CompareExchange(ref assetVersion,0,0);if(assets!=paintedAssets){paintedAssets=assets;changed=true;}
   if(download!=null){if(download.Finished && !downloadHandled){downloadHandled=true;if(download.Cancelled)DownloadError="Download cancelled";else if(download.Error!=""){DownloadError=download.Error;if(DownloadFailed!=null)DownloadFailed(download.Error);}else {queuedImports[download.Set.Id]=true;if(Downloaded!=null)Downloaded(download.Set,download.Final);}changed=true;}else if(!download.Finished && download.Bytes!=paintedBytes && DateTime.UtcNow.Ticks-paintedAt>TimeSpan.TicksPerMillisecond*150){paintedBytes=download.Bytes;paintedAt=DateTime.UtcNow.Ticks;changed=true;}}
   if(changed)Revision++;return changed;
  }
 }
}
